using Sharpmake;
using System.IO;

[Generate]
public class Externals : BaseProject
{
    public Externals()
        : base()
    {
        Name = "Externals";
        SourceRootPath = "Src";
    }

    public override void ConfigureAll(Project.Configuration conf, CommonTarget target)
    {
        base.ConfigureAll(conf, target);
        conf.Output = Configuration.OutputType.Lib;

        // SDL, the window and input on every platform (imgui_impl_sdl3 here; the engine's window). The DLL is copied
        // next to the executables with the rest (Engine.sharpmake.cs).
        // ImGui's renderer backends are named rather than kept in DX11/ and OpenGL/ folders (BaseProject), which would
        // mean editing ImGui's own files: they include "imgui.h" beside them.
        if (target.Platform == Platform.win64)
        {
            conf.LibraryPaths.Add(Globals.ThirdPartyLibDir);
            conf.LibraryFiles.Add("SDL3");

            conf.SourceFilesBuildExcludeRegex.Add(@"[\\/]imgui[\\/]imgui_impl_opengl3\.cpp$");
        }
        else
        {
            conf.LibraryFiles.Add("libSDL3.so");

            conf.SourceFilesBuildExcludeRegex.Add(@"[\\/]imgui[\\/]imgui_impl_dx11\.cpp$");

            // All of it is someone else's code (ImGui and its add-ons, glad, SPIRV-Cross): its warnings would fail the
            // build (-Werror), as OptickCore's would
            conf.AdditionalCompilerOptions.Add("-w");

            // The GL loader generated by glad (Src/OpenGL/glad): GL 4.5 core and KHR_debug. For this project and the ones
            // that use it.
            conf.IncludePaths.Add(Path.Combine("[project.SharpmakeCsPath]", "Src/OpenGL/glad/include"));
        }
    }
}